suppressMessages(library(dplyr))
setwd("/Users/hanno/Documents/GitHub/german_election_data")
fh<-readRDS("data/federal_elections/municipality_level/final/federal_muni_harm_21.rds")
cv<-readRDS("data/covars_municipality/final/ags_area_pop_emp.rds")
j<-fh%>%filter(election_year %in% c(1990,1994,1998,2002,2005,2009,2013,2017,2021))%>%inner_join(cv%>%transmute(ags_21,year,pop=population_ags*1000),by=c("ags"="ags_21","election_year"="year"))%>%filter(pop>=500)%>%mutate(r=eligible_voters_orig/pop,r2=eligible_voters/pop)
print(as.data.frame(j%>%group_by(election_year)%>%summarise(n=n(),med=median(r,na.rm=T),p1=quantile(r,.01,na.rm=T),p99=quantile(r,.99,na.rm=T),gt1=sum(r>1,na.rm=T),lt.4=sum(r<.4,na.rm=T),med2=median(r2,na.rm=T),p99b=quantile(r2,.99,na.rm=T),gt1b=sum(r2>1,na.rm=T))),digits=3)
print(as.data.frame(j%>%filter(election_year==2021)%>%arrange(desc(r))%>%select(ags,ags_name,eligible_voters_orig,pop,r)%>%head(8)))
print(as.data.frame(j%>%filter(election_year==2021)%>%arrange(r)%>%select(ags,ags_name,eligible_voters_orig,pop,r)%>%head(8)))
print(as.data.frame(cv%>%filter(ags_21=="12065251")%>%select(year,population_ags,area_ags)%>%filter(year%in%1998:2004)))
